# Autoscaling with placement constraints and rolling updates.
#
# Demonstrates: horizontal + event-driven scaling, scheduled minimums,
#               stabilization windows, placement constraints, rolling updates.
# Run with:  cca apply examples/autoscaling.ccattler
#
# Expected: web scales 3–30 based on CPU, requests, and queue depth.
#           Minimum 10 instances during weekday business hours.
#           Architecture constraint ensures amd64 nodes only.
#           Zone spread distributes instances across availability zones.
#           Image updates roll out gradually with max 1 unavailable.

service web {
    image nginx:1.28
    instances 3
    expose 8080

    resources {
        cpu 500m
        memory 512Mi
    }

    scale {
        horizontal {
            min 3
            max 30
            target cpu = 60
            target requests_per_second = 500
            event payments.pending = 20
            schedule {
                days weekdays
                start "08:00"
                end "18:00"
                minimum 10
            }
            stabilization {
                scale_up 60s
                scale_down 300s
            }
        }
    }

    placement {
        architecture amd64
        zone spread
    }

    update {
        max_unavailable 1
        max_extra 1
    }
}

# Health check probes.
#
# Demonstrates: HTTP health check with path and interval, TCP health check.
# Run with:  cca run examples/health-checks.ccattler
#            (requires real processes that listen on the declared ports)
#
# Expected: web instances are probed at GET /health every 10s.
#           database instances are probed via TCP connect every 5s.
#           Status output shows health=healthy or health=unhealthy per instance.

service web {
    image nginx:1.28
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
    health {
        http /health
        every 10s
    }
}

service database {
    image postgres:16
    instances 1
    expose 5432
    resources {
        cpu 1000m
        memory 2048Mi
    }
    health {
        tcp
        every 5s
    }
}

# Multiple services with different resource profiles.
#
# Demonstrates: two independent services, different instance counts,
#               different ports, different resource allocations.
# Run with:  cca apply examples/multi-service.ccattler
#
# Expected: web gets 4 instances spread across nodes, api gets 2.
#           Each service has its own resource footprint.

service web {
    image nginx:1.28
    instances 4
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}

service api {
    image myapp:latest
    instances 2
    expose 3000
    resources {
        cpu 250m
        memory 256Mi
    }
}

# Persistent storage: volumes survive node moves.
#
# Demonstrates: volume declaration, service-to-volume binding, exclusive attach
#               (ReadWriteOnce), volume migration on node failure.
# Run with:  cca demo-storage   (built-in with node kill + volume migration)
#
# Expected: postgres gets 1 instance with volume pgdata attached at /var/lib/postgresql/data.
#           web runs 3 instances with no volume (unaffected by storage).
#           If the node running postgres dies, the volume detaches and reattaches
#           to the replacement instance on a surviving node.

volume pgdata {
    size 50Gi
    persistent true
}

service postgres {
    image postgres:16
    instances 1
    expose 5432
    resources {
        cpu 1000m
        memory 2048Mi
    }
    volume pgdata /var/lib/postgresql/data
}

service web {
    image nginx:1.28
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}

# Container deployment with config file and networking.
#
# Demonstrates: real Docker containers, config file mounting, cluster-network
#               IP allocation, exposed port.
# Run with:  cca run-container examples/web-container.ccattler
#
# Expected: 2 nginx instances, each with a custom index.html mounted via config,
#           allocated IPs from 10.100.x.y subnet, port 80 exposed.

service web {
    image nginx:1.28
    instances 2
    expose 80
    resources {
        cpu 500m
        memory 512Mi
    }
    config {
        file "/usr/share/nginx/html/index.html" = "<h1>Hello from CCattler</h1>"
    }
}

# Simple demo: runs 3 sleep processes.
# In production, image would be a container reference.
# For process runtime, image is the shell command to execute.

service web {
    image "sleep 300"
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}
